import{c as t,Q as s,j as o,m as n}from"./chunks/framework.BqPkuuVc.js";const p=JSON.parse('{"title":"Exporting data","description":"","frontmatter":{},"headers":[],"relativePath":"user/after-the-event/exports.md","filePath":"user/after-the-event/exports.md"}'),r={name:"user/after-the-event/exports.md"};function a(i,e,l,h,d,g){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="exporting-data" tabindex="-1">Exporting data <a class="header-anchor" href="#exporting-data" aria-label="Permalink to &quot;Exporting data&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers sharing results and event data with federations, Eventor, other software, or the club.</p><p>What Manager can export, where each export lives, and what goes into the files.</p><h2 id="what-you-can-export-and-where" tabindex="-1">What you can export, and where <a class="header-anchor" href="#what-you-can-export-and-where" aria-label="Permalink to &quot;What you can export, and where&quot;">​</a></h2><p>Each export lives on the screen it belongs to:</p><table tabindex="0"><thead><tr><th>What</th><th>Where</th><th>Formats</th></tr></thead><tbody><tr><td><strong>Results</strong></td><td><strong>Results → Publish</strong></td><td>IOF XML, JSON, PDF, print, upload to Eventor, a sheet on the splits printer</td></tr><tr><td><strong>Start list</strong></td><td><strong>Starts → Start list</strong> tab <strong>→ Actions</strong></td><td>IOF XML, JSON, CSV, PDF, print, upload to Eventor</td></tr><tr><td><strong>Entry list</strong></td><td><strong>Competitors → Actions → Export entry list</strong></td><td>IOF XML, JSON, CSV</td></tr><tr><td><strong>Start blocks</strong></td><td><strong>Competitors → Actions</strong>, or the class&#39;s <strong>Assign blocks</strong> dialog</td><td>CSV, JSON</td></tr><tr><td><strong>Bib numbers</strong></td><td>The <strong>Actions</strong> menu of <strong>Allocate bib numbers</strong></td><td>CSV (one row per event, or one per person), JSON</td></tr><tr><td><strong>Changes report</strong></td><td><strong>Competitors → Actions → Changes report → Actions</strong></td><td>PDF, CSV, JSON</td></tr><tr><td><strong>Carnival standings</strong></td><td>The multi-stage event&#39;s <strong>Standings</strong> tab → <strong>Actions</strong></td><td>CSV, PDF</td></tr><tr><td><strong>Knock-out classification</strong></td><td>The knock-out competition&#39;s <strong>Classification</strong> tab</td><td>CSV</td></tr><tr><td><strong>A GPS track</strong></td><td><strong>Tracking</strong>, beside each athlete unit</td><td>GPX</td></tr><tr><td><strong>Results, every few minutes, for another system</strong></td><td><strong>Event details → Backup &amp; export → Live export</strong></td><td>IOF XML — one file overwritten each time, or a new file for each export</td></tr><tr><td><strong>Live results online</strong></td><td><strong>Event details → Live results</strong> (liveresultat), and cloud sync</td><td>Sent straight there — see <a href="./../running-the-event/publishing-live-results">Publishing live results online</a></td></tr><tr><td><strong>The whole event</strong></td><td>The event&#39;s card on the <strong>Events</strong> list → <strong>Backup event</strong></td><td>A backup zip</td></tr></tbody></table><p><strong>IOF XML</strong> is the orienteering standard (version 3.0), read by Eventor, federation systems, WinSplits, SplitsBrowser, Livelox and other timing software. <strong>JSON</strong> is <a href="./../advanced/orienteering-json">Orienteering JSON (OJSON)</a>, which carries everything the XML does and more. <strong>CSV</strong> opens in a spreadsheet.</p><p>There is no CSV of results. Results go out as IOF XML or JSON for other software, and as a PDF or print for people. The exceptions are a carnival&#39;s overall standings and a knock-out&#39;s classification, which both export as CSV (see <a href="#exporting-a-multi-stage-event">Exporting a multi-stage event</a>).</p><p>Every export is of the event as it stands at that moment. Exporting changes nothing in the event, and isn&#39;t recorded in its <a href="./../reference/audit-trail">audit trail</a>. The one exception is an upload to Eventor, which can save the event&#39;s Eventor link (below).</p><h2 id="results-files" tabindex="-1">Results files <a class="header-anchor" href="#results-files" aria-label="Permalink to &quot;Results files&quot;">​</a></h2><p><strong>Publish → Export IOF XML…</strong>, <strong>Export JSON…</strong> and <strong>Upload to Eventor…</strong> on the <a href="./results">Results</a> screen produce the results file other systems keep. Before any of them, Manager checks that everyone in the classes you chose has a settled result. A file has to say what became of everybody who took part. See <a href="./results#settling-everyone-first">Settling everyone first</a>, and <a href="./../reference/status-and-race-time#what-an-exported-results-file-contains">What an exported results file contains</a> for how each status is written.</p><p>The <strong>Publish options</strong> dialog then asks:</p><ul><li><strong>Classes</strong> — which classes go in. Everything is ticked to begin with.</li><li><strong>Include DNS competitors</strong> — whether competitors marked <strong>DNS</strong> are in the file.</li><li><strong>Countries</strong> — for the files only, when there&#39;s more than one (below).</li><li><strong>Relay or individual</strong> — at an event with both, because a results file never mixes the two (see <a href="./../event-setup/relay-events">Relay events</a>).</li><li><strong>IOF XML options</strong> — for the IOF XML only: combined classes, and leaving out organisation ids (below).</li></ul><p><strong>Export PDF…</strong> and <strong>Print view…</strong> make a document for people rather than software, laid out like the Results screen. See <a href="./results#publishing-the-final-results">Publishing the final results</a>.</p><h3 id="splits" tabindex="-1">Splits <a class="header-anchor" href="#splits" aria-label="Permalink to &quot;Splits&quot;">​</a></h3><p>Both results files carry each competitor&#39;s <strong>split times</strong>: one per control, in course order, so split-analysis tools such as WinSplits, SplitsBrowser and Livelox can draw the race. The IOF XML gives them in whole seconds, as those tools expect; the JSON gives them to the millisecond, and says whether each came from the card or a radio control. Nothing has to be switched on.</p><h3 id="exporting-one-country-s-results" tabindex="-1">Exporting one country&#39;s results <a class="header-anchor" href="#exporting-one-country-s-results" aria-label="Permalink to &quot;Exporting one country&#39;s results&quot;">​</a></h3><p><strong>Publish → Export IOF XML</strong> and <strong>Publish → Export JSON</strong> open a dialog that, alongside the classes, asks which <strong>Countries</strong> to include. Everything starts selected, so the file carries every country unless you untick some — handy when a national federation wants only its own runners.</p><ul><li>A competitor&#39;s country is their <strong>club&#39;s</strong>. A relay team goes by the team&#39;s own club, so a team is always exported whole.</li><li><strong>No country</strong> covers competitors whose club has no country recorded (or has a dash, <code>-</code>, where the code would be), and competitors with no club at all.</li><li>Places are not renumbered. A runner who came fourth in the class is fourth in the file, whoever else was left out.</li><li>The list only appears when there is more than one choice — a single country plus <strong>No country</strong> counts. The PDF, Print and <strong>Upload to Eventor</strong> actions don&#39;t offer it: Eventor must get every runner in each class you upload, or it reads the rest as never having entered.</li></ul><p>Each country shows with the code its clubs were given. If some clubs were given the IOC code (<code>SUI</code>) and others the ISO code (<code>CHE</code>), both appear — tick both.</p><h3 id="combining-classes-for-the-world-ranking-iof-xml" tabindex="-1">Combining classes for the World Ranking (IOF XML) <a class="header-anchor" href="#combining-classes-for-the-world-ranking-iof-xml" aria-label="Permalink to &quot;Combining classes for the World Ranking (IOF XML)&quot;">​</a></h3><p>The IOF asks a World Ranking event for a results file in which every class that ran a course is merged into one list and ordered — the ranking points are worked out over everyone on the course, not class by class. At a Middle where M21E and M20E run one course, and W21E and W20E another, that is two merged lists; at a sprint where M18A runs with them, three classes in each.</p><p><strong>Publish → Export IOF XML</strong> has an <strong>IOF XML options</strong> line for this: click <strong>Change</strong> beside it. In the dialog that opens, either click <strong>Combine by course</strong> — each set of the classes in the export that ran the same course becomes one combined class — or click <strong>Add combined class</strong> and pick its classes yourself. Click <strong>Done</strong>, check the line in Publish options now lists your combined classes, and export as usual. Nothing is remembered: the next export starts again with nothing combined.</p><ul><li>Each combined class is published once, with everyone in it ordered by time. <strong>Places and time behind are worked out across the combined list</strong>, so an M20E runner who beat half of M21E is placed among them.</li><li>Each combined class has a <strong>Class name</strong>, <strong>Class id</strong> and <strong>Course name</strong>. Left blank, the file uses its own: the class is named after its classes (<strong>M21E + M20E</strong>) with their ids joined (<strong>1+2</strong>), and the course after the class. Fill them in when the World Ranking event was set up with names of its own — <strong>Men</strong>, <strong>ME</strong> and so on. Two classes in one file can&#39;t have the same id; the dialog says so beside the field.</li><li>Nothing in the event changes. The classes stay separate everywhere else — on screen, in the JSON export, in the PDF and on Eventor. Export the ordinary file as well if anyone needs the classes apart.</li><li><strong>Combine by course</strong> counts classes as running the same course when they were given the same courses on the <strong>Classes</strong> page; a class alone on its course is left as it is. Only individual classes can be combined — never relay classes — and a class can be in one combined class only.</li><li>Classes you leave ticked but that aren&#39;t combined are exported as normal alongside — untick them from <strong>Classes</strong> if the IOF wants the World Ranking classes only. Untick a class you combined and it simply drops out of its combined class.</li></ul><h4 id="leaving-out-organisation-ids" tabindex="-1">Leaving out organisation ids <a class="header-anchor" href="#leaving-out-organisation-ids" aria-label="Permalink to &quot;Leaving out organisation ids&quot;">​</a></h4><p>The same dialog has <strong>Leave out organisation ids</strong>. Each competitor&#39;s club is still named in the file, with its country; only the club&#39;s Eventor organisation number is left out (a club that isn&#39;t an Eventor organisation never has one in the file — see <a href="./../reference/club-registry">Club registry</a>). That number means nothing to a system that numbers clubs its own way, such as the IOF World Ranking, which may otherwise try to match on it. A relay team&#39;s club keeps its id.</p><h2 id="uploading-to-eventor" tabindex="-1">Uploading to Eventor <a class="header-anchor" href="#uploading-to-eventor" aria-label="Permalink to &quot;Uploading to Eventor&quot;">​</a></h2><p><strong>Results → Publish → Upload to Eventor…</strong> and <strong>Actions → Upload to Eventor</strong> on the start list send the results or the start list straight to Eventor, without saving a file. Both need Eventor set up in <strong>Settings → Eventor</strong>, with your organisation&#39;s API key.</p><ol><li>Choose the classes in <strong>Publish options</strong>, as for a file.</li><li>Choose the <strong>Eventor event</strong>. An event created from Eventor, or one you&#39;ve uploaded to before, already has it chosen. Otherwise, pick it from your organisation&#39;s events, and Manager remembers the choice as the event&#39;s Eventor link.</li><li>Click <strong>Upload</strong>.</li></ol><p>Things to know:</p><ul><li><strong>Eventor needs every runner in each class you send.</strong> That&#39;s why there&#39;s no <strong>Countries</strong> choice for an upload: a class with runners left out reads on Eventor as though they never entered.</li><li><strong>Nothing is uploaded if Eventor is missing a class.</strong> If the Eventor event has no class for one you&#39;re sending, the upload stops and names the classes. Leave those out in <strong>Publish options</strong>, or add them to the event in Eventor, and upload again.</li><li><strong>Corrections need another upload.</strong> Changing a result in Manager doesn&#39;t change what Eventor already has. Upload again once it&#39;s fixed.</li></ul><h2 id="start-lists" tabindex="-1">Start lists <a class="header-anchor" href="#start-lists" aria-label="Permalink to &quot;Start lists&quot;">​</a></h2><p>The start list goes out from <strong>Actions</strong> on the <strong>Start list</strong> tab of <strong>Starts</strong>: IOF XML, JSON, a CSV that Manager&#39;s own CSV entry import reads back, a PDF, a print view, and an upload to Eventor. All three files can be imported back into Manager. See <a href="./../event-setup/start-draw#the-start-list-tab">The Start list tab</a> and <a href="./../event-setup/start-draw#uploading-the-start-list-to-eventor">Uploading the start list to Eventor</a>.</p><h2 id="exporting-the-entry-list" tabindex="-1">Exporting the entry list <a class="header-anchor" href="#exporting-the-entry-list" aria-label="Permalink to &quot;Exporting the entry list&quot;">​</a></h2><p>Who has entered — as opposed to when they start or how they got on — is exported from the <strong>Competitors</strong> page: <strong>Actions → Export entry list</strong>, in IOF XML, OJSON or CSV. It&#39;s written up where the menu lives: see <a href="./../event-setup/competitors-clubs-teams#exporting-the-entry-list">Exporting the entry list</a>.</p><p>Two things worth knowing before you reach for it:</p><ul><li><strong>The export is always the whole event</strong>, never the filtered list you&#39;re looking at.</li><li><strong>The CSV is designed to be edited and re-imported</strong> — though not every column comes back. The <a href="./../event-setup/competitors-clubs-teams#the-csv-round-trip">round-trip table</a> says which do.</li></ul><h2 id="exporting-a-multi-stage-event" tabindex="-1">Exporting a multi-stage event <a class="header-anchor" href="#exporting-a-multi-stage-event" aria-label="Permalink to &quot;Exporting a multi-stage event&quot;">​</a></h2><p>Both standings exports live on the <strong>Actions</strong> menu of the carnival&#39;s Standings tab, alongside Recompute.</p><p><strong>Overall standings as CSV</strong> — <strong>Export CSV</strong>. One row per competitor, one column per stage, plus the total: the shape a prize-giving spreadsheet wants. A stage that didn&#39;t count is bracketed rather than blanked, and a provisional total keeps its <code>*</code>, so the file says what the screen said. Export one class or all of them.</p><p><strong>Overall standings as PDF</strong> — <strong>Export PDF</strong>. The table laid out for printing or pinning up, matching whatever you have on screen: the class or combined view you have selected, and your Show and Times settings.</p><p><strong>IOF XML per stage</strong> — export a stage&#39;s results as IOF XML the usual way. Because the event is a stage, the file also carries the stage&#39;s <code>raceNumber</code> and each competitor&#39;s overall standing <em>after that stage</em> as an IOF <code>OverallResult</code>. Every stage up to it has to be settled first — a runner left with no status on an earlier day holds the file up, and the export tells you who (see <a href="./../reference/status-and-race-time#what-an-exported-results-file-contains">What an exported results file contains</a>). That is the IOF standard&#39;s own answer to multi-stage results, so SplitsBrowser, Eventor and Livelox read it with no bespoke format. A standalone event&#39;s export is unchanged.</p><p>See <a href="./../event-setup/multi-stage-events#exporting-a-carnival">Multi-stage events</a>.</p><p><strong>A knock-out competition&#39;s classification</strong> — <strong>Export CSV</strong> at the top of its <strong>Classification</strong> tab: one row per competitor with their overall place, and the place they took in each round. There is no total time, because a knock-out has none. Each round&#39;s own results export normally, as any event&#39;s do. See <a href="./../event-setup/knock-out-competitions#downloading-it">Knock-out competitions</a>.</p><h2 id="how-a-competitor-is-identified-in-an-exported-file" tabindex="-1">How a competitor is identified in an exported file <a class="header-anchor" href="#how-a-competitor-is-identified-in-an-exported-file" aria-label="Permalink to &quot;How a competitor is identified in an exported file&quot;">​</a></h2><p>Every results, start-list and entry-list export — IOF XML, OJSON and <strong>Upload to Eventor</strong> alike — names each competitor by the identifiers they hold: their <strong>Eventor ID</strong> (your own competitor number) and their <strong>IOF ID</strong>. In IOF XML the competitor number comes first and the IOF ID follows it marked as the IOF&#39;s, so a system that reads only the first one still finds the number it always did. A competitor holding neither is exported by name alone. The CSV entry and start lists carry both as the <strong>Database Id</strong> and <strong>IOF Id</strong> columns, and all of them read both back when imported into Manager.</p><p>To fill in IOF IDs for a field that arrived without them, see <a href="./../event-setup/import-event-data#importing-iof-ids">Importing IOF IDs</a>.</p><h2 id="exporting-as-ojson" tabindex="-1">Exporting as OJSON <a class="header-anchor" href="#exporting-as-ojson" aria-label="Permalink to &quot;Exporting as OJSON&quot;">​</a></h2><p>Everything Manager exports as IOF XML it also exports as <strong>OJSON</strong> — a published format with a JSON Schema, carrying the things the XML has no room for: split-time columns as data, a relay team&#39;s own result, whether a split came from a card or a radio, and millisecond precision. If you are writing something that reads a Manager event — a club results page, a spreadsheet pipeline, an app — that is the format to read.</p><p>See <a href="./../advanced/orienteering-json">OJSON</a> for the endpoints, the field reference and the schema.</p><h2 id="gps-tracks" tabindex="-1">GPS tracks <a class="header-anchor" href="#gps-tracks" aria-label="Permalink to &quot;GPS tracks&quot;">​</a></h2><p>At an event with meshO athlete units, <strong>Tracking</strong> has a <strong>Download GPX track</strong> button beside each unit. It saves the route that unit recorded as a GPX file, which mapping and route-analysis software opens. See <a href="./../running-the-event/tracking">Tracking</a>.</p><h2 id="keeping-the-event-afterwards" tabindex="-1">Keeping the event afterwards <a class="header-anchor" href="#keeping-the-event-afterwards" aria-label="Permalink to &quot;Keeping the event afterwards&quot;">​</a></h2><p>An export is a copy for somebody else. To keep the event itself, take a <strong>backup</strong>: one zip holding everything, from the punches to the audit trail, that restores into Manager exactly as it was. Take one when the results are final and keep it somewhere other than the laptop. See <a href="./../reference/backup-and-restore">Backup and restore</a>.</p><p>Every card read is also kept on disk as its own file, whether or not you back up. See <a href="./../reference/backup-and-restore#card-downloads-are-always-kept-twice">Card downloads are always kept twice</a>.</p><p>If cloud sync is on, finishing the event also publishes it to the meshO cloud, where spectators can browse the results online (see <a href="./../running-the-event/publishing-live-results#publishing-to-the-mesho-cloud">Publishing to the meshO cloud</a>).</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./results">Results</a> — the Results screen and the Publish menu</li><li><a href="./../reference/status-and-race-time#what-an-exported-results-file-contains">Status and race time rules</a> — what a results file contains</li><li><a href="./../advanced/orienteering-json">OJSON</a> — the format behind every <strong>Export JSON</strong></li><li><a href="./../event-setup/competitors-clubs-teams#exporting-the-entry-list">Competitors, clubs and teams</a> — exporting the entry list</li><li><a href="./../event-setup/multi-stage-events">Multi-stage events</a> — exporting overall standings</li><li><a href="./../reference/backup-and-restore">Backup and restore</a></li><li><a href="./../running-the-event/publishing-live-results">Publishing live results online</a> — liveresultat, the meshO cloud and the live export</li><li><a href="./changes-report">Changes report</a> — what changed about people, exported as PDF, CSV or JSON</li></ul>',58)])])}const u=t(r,[["render",a]]);export{p as __pageData,u as default};
